-- 3. Insert UserShipAssignments
SELECT u.UserId, a.ShipCode
FROM (VALUES
    ('admin', 'SHIP01'), ('admin', 'SHIP02'), ('admin', 'SHIP03'), ('admin', 'SHIP04'), ('admin', 'SHIP05'), ('admin', 'SHIP06'),
    ('fleet.manager', 'SHIP01'), ('fleet.manager', 'SHIP02'), ('fleet.manager', 'SHIP03'),
    ('supt.deck', 'SHIP01'), ('supt.deck', 'SHIP02'),
    ('supt.engine', 'SHIP03'), ('supt.engine', 'SHIP04'),
    ('crew.officer', 'SHIP01'), ('crew.officer', 'SHIP02'), ('crew.officer', 'SHIP04')
) AS a(Username, ShipCode)
INNER JOIN dbo.Users u ON a.Username = u.Username;
